// 任何分支都要能走到这里 —— 失败也要留下一行可读的执行快照（GEO 发布流踩过：
// 某个分支走不到回报，出了问题只能靠猜）。
const r = $input.first().json || {};
let note;
if (r.skipped) {
  note = `跳过：${r.reason || '距上次生成太近'}`;
} else if (r.ok) {
  note = `已重发：${r.groups} 个店型页，挂上 ${r.guides_linked} 篇指南，`
       + `${r.guide_categories_mapped} 个类目可回链`;
} else {
  note = '重发失败 —— 看控制台 backend 日志（WP 打不通或凭据过期）';
}
return [{ json: { ...r, note } }];
